const fs = require('fs');
const path = require('path');

const GREETING = 'Hello team';
const OUTPUT_FILE = path.join(__dirname, 'greeting.txt');

fs.writeFileSync(OUTPUT_FILE, `${GREETING}\n`, 'utf8');

console.log(`Wrote ${GREETING} to ${OUTPUT_FILE}`);

